"""Configuration loading helpers."""

from pathlib import Path


def config_path(name: str) -> Path:
    return Path("configs") / name


def load_retry_policy() -> dict:
    return {"initial_delay_seconds": 30, "max_attempts": 5}


def load_feature_flags() -> dict:
    """Load feature flags from configs/feature_flags.yaml.

    Returns a nested dict of sections to flags. Missing files or sections
    yield empty mappings so callers can fall back to default behavior.
    """
    path = config_path("feature_flags.yaml")
    if not path.exists():
        return {}

    flags: dict = {}
    current_section: str | None = None
    for raw_line in path.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.endswith(":"):
            current_section = line[:-1].strip()
            flags.setdefault(current_section, {})
            continue
        if ":" in line and current_section is not None:
            key, _, value = line.partition(":")
            flags[current_section][key.strip()] = _parse_scalar(value.strip())
    return flags


def _parse_scalar(value: str):
    if value == "true":
        return True
    if value == "false":
        return False
    return value

